/**
    this code should be run in the browser console, in order to pass the cookie check from the server
    1. log in to Finance Yahoo first: finance.yahoo.com (with premium active account)
    2. open https://query1.finance.yahoo.com/ws/value-analyzer/v1/finance/premium/valueAnalyzer?formatted=true&lang=en-US&region=US&symbol=AABC&corsDomain=finance.yahoo.com
    3. run the code below in the web console
    ps: request speed must be limited, if requests were sent too quickly, the respond would be 404
**/


function get_request_url(symbol) {
    return 'https://query1.finance.yahoo.com/ws/value-analyzer/v1/finance/premium/valueAnalyzer?formatted=true&lang=en-US&region=US&symbol='+symbol+'&corsDomain=finance.yahoo.com'
}
function download(filename, text) {
    var element = document.createElement('a');
    element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(text));
    element.setAttribute('download', filename);

    element.style.display = 'none';
    document.body.appendChild(element);

    element.click();

    document.body.removeChild(element);
}
function XHR2v2(url, data, params) {
    var self = this;
    var xhr = new XMLHttpRequest();
    data = data || {};
    params = params || {};
    try {
        function _delStr(str) {
            return str.replace(/[^\S\t ]/g, ' ').replace(/[\u0001-\u0008\u000c\u000e-\u001f\u007f]+/g, '');
        }
        // 处理类型
        var type = params['type'] || 'POST';
        // 处理数据参数
        var form;

        if (/GET/i.test(type)) {
            form = '';
            for (var p in data) {
                form = (form == '') ? (p + '=') : (form + '&' + p + '=');
                var valueType = typeof data[p];
                if (valueType == 'string') {
                    form += params.preDeal ? params.preDeal(value) : _delStr(data[p]);
                } else if (valueType == 'number') {
                    form += data[p];
                } else {
                    form += JSON.stringify(data[p]);
                }
            }
        } else {
            form = new FormData();
            for (var p in data) {
                var value = data[p],
                    valueType = typeof value;
                if (value == null) {
                    form.append(p, '');
                } else if (valueType == 'number' || value.toString() == '[object File]') {
                    form.append(p, value);
                } else {
                    if (valueType != 'string') {
                        value = JSON.stringify(value);
                    }
                    value = params.preDeal ? params.preDeal(value) : _delStr(value);
                    form.append(p, params.encodeURIComponent ? encodeURIComponent(value) : value);
                }
            }
        }
        // 超时
        params.timeout > 0 && (xhr.timeout = params.timeout);
        // 添加回调函数
        xhr.ontimeout = function (){
            params.onLoad('timeout!');
        };
        xhr.onload = function(e,r) {
            // console.log('----onload---');
            if (this.status != 200 || !this.responseText) {
                if(this.status ==404){
                    bad_request++;
                }
                params.onLoad(this);
            }else {
                params.onLoad(null, this.responseText);
            }
        };

        xhr.onabort = params['onabort'];
        xhr.onerror = function(e) {
            console.log(e.stack);
            params.onLoad(e);
        };

        xhr.open(type, url, true);
        // xhr 发送头参数设置
        if (!window.XDomainRequest && (type.toUpperCase() == 'GET')) {
            xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded;");
        }
        xhr.send(form);
    } catch (e) {
        console.log(e.stack);
        console.log("请求失败： " + e.message);
    }
    return xhr;
}


function send_request(symbol, cb){
    let url = get_request_url(symbol);
    XHR2v2(url, null, {type: 'GET', onLoad:function (error,resp_text){
        if(error){
            download('error_va_'+symbol+'.txt', 'url:'+url+',     error'+JSON.stringify(error))
        }else{
            download('value_analyse_'+symbol+'.txt', resp_text)
        }
        cb(error)
    }});
}
